//
// ===== Filtri ICT (stessa logica del denominatore) =====
//

VAR lvl1 = VALUES('GDS_Line'[ICT_lvl_1])

VAR lvl2_con_blank =
    UNION(
        VALUES('GDS_Line'[ICT_lvl_2]),
        ROW("ICT_lvl_2", BLANK()),
        ROW("ICT_lvl_2", ""),
        ROW("ICT_lvl_2", "NaN")
    )

VAR lvl2_filtrato = ISFILTERED('GDS_Line'[ICT_lvl_2])

//
// ===== JMBI =====
//

VAR T_JMBI_ICT =
CALCULATETABLE(
    SELECTCOLUMNS(
        'Jira Macro Business Initiative',
        "IM_norm", 'Jira Macro Business Initiative'[Issue Investment Memo]
    ),
    'Jira Project List'[Project_Status] <> "Demo Project"
--    TREATAS(VALUES('GDS_Line'[ICT_lvl_1]), 'Jira Macro Business Initiative'[GDS_line_prj])
--    TREATAS(VALUES('GDS_Line'[ICT_lvl_2]), 'Jira Macro Business Initiative'[Factory_Chapter]) serve capire il secondo livello
)

//
// ===== Lista IM approvati (solo livello 1) =====
//

VAR tab_ICT_lvl1 =
CALCULATETABLE(
    VALUES('Jira Demand'[Issue Investment Memo]),
    'Jira Investment Memo'[Issue_status] = "Approved",
    TREATAS(lvl1, 'Jira Business Need'[1st richiedente])
)

//
// ===== Lista IM approvati (livello 1 + livello 2) =====
//

VAR tab_ICT_lvl2 =
CALCULATETABLE(
    VALUES('Jira Demand'[Issue Investment Memo]),
    'Jira Investment Memo'[Issue_status] = "Approved",
    TREATAS(lvl1, 'Jira Business Need'[1st richiedente]),
    TREATAS(lvl2_con_blank, 'Jira Business Need'[2nd richiedente])
)

VAR n_lvl1 = COUNTROWS(DISTINCT(INTERSECT(T_JMBI_ICT, tab_ICT_lvl1)))
VAR n_lvl2 = COUNTROWS(DISTINCT(INTERSECT(T_JMBI_ICT, tab_ICT_lvl2)))

RETURN
COALESCE(IF(lvl2_filtrato, n_lvl2, n_lvl1), 0)







