VAR _IM_validi =
CALCULATETABLE(
    VALUES('Jira Demand'[Issue Investment Memo]),
    KEEPFILTERS('Jira Investment Memo'[Issue_status] = "Approved"),
    TREATAS(VALUES('GDS_Line'[ICT_lvl_1]), 'Jira Business Need'[1st richiedente]),
    TREATAS(VALUES('GDS_Line'[ICT_lvl_2]), 'Jira Business Need'[2nd richiedente])
)

var calcolo_filtrato =
CALCULATE(
    SUM('Jira Demand'[Total Cost]),
    // Restringe la somma ai soli IM validi
    KEEPFILTERS(
        TREATAS(
            _IM_validi,
            'Jira Demand'[Issue Investment Memo]
        )
    )
)

RETURN 
COALESCE(calcolo_filtrato, 0 )

VAR IssueKey = SELECTEDVALUE('Jira Macro Business Initiative'[Issue key])
var valore = 
IF(
    NOT ISBLANK(IssueKey),
    CALCULATE(
        MAX('Jira Issue Detail'[Gds_line_prj]),
        KEEPFILTERS('Jira Issue Detail'[issue_key] = IssueKey)
    )
)

RETURN IF(valore = "" || ISBLANK(valore), BLANK(), valore)

VAR IssueKey = SELECTEDVALUE('Jira Epic'[feature_delivery])
var valore = 
IF(
    NOT ISBLANK(IssueKey),
    CALCULATE(
        MAX('Jira Issue Detail'[Gds_line_prj]),
        KEEPFILTERS('Jira Issue Detail'[issue_key] = IssueKey)
    )
)

RETURN IF(valore = "" || ISBLANK(valore), "", valore)

VAR IssueKey = SELECTEDVALUE('Jira Epic'[apm_list])
var valore = 
IF(
    NOT ISBLANK(IssueKey),
    CALCULATE(
        MAX(APM[DE_LEVEL_1]),
        KEEPFILTERS(APM[APM Code] = IssueKey)
    )
)

RETURN IF(valore = "" || ISBLANK(valore), "", valore)

CALCULATE(
    DISTINCTCOUNT('MBI Transition Status'[issue_key]),
    NOT ISBLANK('MBI Transition Status'[Lead Time - OpenApproved])
)

// COUNT Open_Approved =  CALCULATE(COUNTROWS('MBI Transition Status'), 'MBI Transition Status'[from_status] = "Open", 'MBI Transition Status'[to_status] = "Prepared")

CALCULATE(
    DISTINCTCOUNT('MBI Transition Status'[issue_key]),
    NOT ISBLANK('MBI Transition Status'[Lead Time - HighlevelFunctionalApproved])
)

// COUNT Open_Approved =  CALCULATE(COUNTROWS('MBI Transition Status'), 'MBI Transition Status'[from_status] = "Open", 'MBI Transition Status'[to_status] = "Prepared")

CALCULATE(
    DISTINCTCOUNT('MBI Transition Status'[issue_key]),
    NOT ISBLANK('MBI Transition Status'[Lead Time - TechEvaluationEstimationDone])
)

// COUNT Open_Approved =  CALCULATE(COUNTROWS('MBI Transition Status'), 'MBI Transition Status'[from_status] = "Open", 'MBI Transition Status'[to_status] = "Prepared")

CALCULATE(
    DISTINCTCOUNT('MBI Transition Status'[issue_key]),
    NOT ISBLANK('MBI Transition Status'[Lead Time - HighLevelFunctionalRequirement-TechEvaluation])
)

// COUNT Open_Approved =  CALCULATE(COUNTROWS('MBI Transition Status'), 'MBI Transition Status'[from_status] = "Open", 'MBI Transition Status'[to_status] = "Prepared")

CALCULATE(
    DISTINCTCOUNT('Jira Initiative Estimation'[issue_key]),
    NOT 'Jira Initiative Estimation'[issue_status] IN { "Open", "Rejected" }
)

var calcolo = 
CALCULATE(
    COUNT('Jira ICR'[Issue]),
    NOT ISBLANK(('Jira ICR'[Issue APM List] )),
    'Jira Feature Delivery'[Issue status] = "Release Completed"
)
return COALESCE(calcolo, 0)

CALCULATE(
    COUNTROWS(
        FILTER(
            VALUES('Jira Business Feature for APM'[Issue]),
            CALCULATE(
                DISTINCTCOUNT('Jira Feature Delivery'[Issue])
            ) >= 2
        )
    )
)

var issue_key = SELECTEDVALUE('Jira Macro Business Initiative'[Issue key])
RETURN
CALCULATE(
    MIN('MBI Transition Status'[transition_date]),
    'MBI Transition Status'[to_status] = "High-Level Functional Requirement"
)

var x = DIVIDE(
    SUMX(
        VALUES('Jira Business Feature for APM 2'[Issue]),
        CALCULATE([FfA Tech Progress]) *
        CALCULATE(COUNTROWS('Jira Issue Detail 3'))
    ),
    SUMX(
        VALUES('Jira Business Feature for APM 2'[Issue]),
        CALCULATE(COUNTROWS('Jira Issue Detail 3'))
    )
)
RETURN COALESCE(x, 0)

CALCULATE (
    DISTINCTCOUNT (
        'MBI Transition Status'[issue_key]
    )
)

CALCULATE (
    COUNTROWS (
        FILTER (
            ALL ( 'IE Transition Status' ),
            'IE Transition Status'[To OrdineBarra Semplificato] = 2
                && 'IE Transition Status'[From OrdineBarra Semplificato] <> 2
        )
    ),
    ALL ()
)

SUMX (
    VALUES (
        'Workflow Fasi MBI Semplificate'[OrdineFase]
    ),
    CALCULATE (
        [MBI Tempo Storico Medio nello Stato Semplificato Leam Time]
    )
)

CALCULATE (
    DISTINCTCOUNT (
        'FD Transition Status'[issue_key]
    )
)

SUMX (
    VALUES (
        'Workflow Fasi FD Semplificate'[OrdineFase]
    ),
    CALCULATE (
        [FD Tempo Storico Medio nello Stato Semplificato]
    )
)

